WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_b_equation'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '设未知数列方程', 'kp-age-b-equation', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "年龄问题万能方程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "过去、现在、将来。列表格设 X，是防止脑子短路的终极防线。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当题目条件交错，出现了三个人的年龄和、年龄倍数，且让你倒推某个年份。无法用代入排除法一眼看穿时。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤（年龄表格法）"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画一个三列矩阵: 过去、现在、将来] --> B[行头写上甲、乙、丙]\nB --> C[设其中最小或最关键的未知年龄为 X]\nC --> D[用 X 把表格里其他的格子全部填满 (切记同增同减原则)]\nD --> E[寻找题目中未被使用的最后一个条件]\nE --> F[利用该条件把表格里的多项加起来或相乘, 形成死等式]"}}]}$$ AS jsonb), NULL, '设未知数列方程的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "设未知数列方程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_b_equation", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
